   250  /**
   251   * Calculates decimal value from hexadecimal ASCII character given in
   252   * @p c. The caller must ensure that @p c actually represents a valid
   253   * heaxdecimal character, e.g. with isxdigit(3).
   254   *
   255   * @hideinitializer
   256   */
   257  #define hexchar_to_dec(c) ((c) & 0x40 ? ((c) & 0x0F) + 9 : ((c) & 0x0F))
   258
   259  /**
   260   * Decodes percent-encoded characters while copying the string @p seg

260   * Decodes percent-encoded characters while copying the string @p seg
   261   * of size @p length to @p buf. The caller of this function must
   262   * ensure that the percent-encodings are correct (i.e. the character
   263   * '%' is always followed by two hex digits. and that @p buf provides
   264   * sufficient space to hold the result. This function is supposed to
   265   * be called by make_decoded_option() only.
   266   *
   267   * @param seg     The segment to decode and copy.
   268   * @param length  Length of @p seg.
   269   * @param buf     The result buffer.
   270   */
   271  static void
   272  decode_segment(const uint8_t *seg, size_t length, unsigned char *buf) {
   273
   274    while (length--) {
   275
   276      if (*seg == '%') {
   277        *buf = (hexchar_to_dec(seg[1]) << 4) + hexchar_to_dec(seg[2]);
   278
   279        seg += 2; length -= 2;
   280      } else {
   281        *buf = *seg;
   282      }
   283
   284      ++buf; ++seg;
   285    }
   286  }
   287
   288  /**
   289   * Runs through the given path (or query) segment and checks if
   290   * percent-encodings are correct. This function returns @c 0 on success
   291   * and @c -1 on error.
   292   */
   293  static int
   294  check_segment(const uint8_t *s, size_t length, size_t *segment_size) {
   295    size_t n = 0;
   296
   297    while (length) {
   298      if (*s == '%') {
   299        if (length < 2 || !(isxdigit(s[1]) && isxdigit(s[2])))
   300                return -1;
   301
   302        s += 2;
   303        length -= 2;
   304      }
   305
   306      ++s; ++n; --length;
   307    }
   308
   309    *segment_size = n;
   310
   311    return 0;
   312  }
