   314  /**
   315   * Writes a coap option from given string @p s to @p buf. @p s should
   316   * point to a (percent-encoded) path or query segment of a coap_uri_t
   317   * object.  The created option will have type @c 0, and the length
   318   * parameter will be set according to the size of the decoded string.
   319   * On success, this function returns @c 0 and sets @p optionsize to the option's
   320   * size. On error the function returns a value less than zero. This function
   321   * must be called from coap_split_path_impl() only.
   322   *
   323   * @param s           The string to decode.
   324   * @param length      The size of the percent-encoded string @p s.
   325   * @param buf         The buffer to store the new coap option.
   326   * @param buflen      The maximum size of @p buf.
   327   * @param optionsize  The option's size.
   328   *
   329   * @return @c 0 on success and @c -1 on error.
   330   *
   331   * @bug This function does not split segments that are bigger than 270
   332   * bytes.
   333   */
   334  static int
   335  make_decoded_option(const uint8_t *s, size_t length,
   336                      unsigned char *buf, size_t buflen, size_t* optionsize) {
   337    int res;
   338    size_t segmentlen;
   339    size_t written;
   340
   341    if (!buflen) {
   342      coap_log(LOG_DEBUG, "make_decoded_option(): buflen is 0!\n");
   343      return -1;
   344    }
   345
   346    res = check_segment(s, length, &segmentlen);
   347    if (res < 0)
   348      return -1;
   349
   350    /* write option header using delta 0 and length res */
   351    written = coap_opt_setheader(buf, buflen, 0, segmentlen);
   352
   353    assert(written <= buflen);
   354
   355    if (!written)                        /* encoding error */
   356      return -1;
   357
   358    buf += written;                /* advance past option type/length */
   359    buflen -= written;
   360
   361    if (buflen < segmentlen) {
   362      coap_log(LOG_DEBUG, "buffer too small for option\n");
   363      return -1;
   364    }
   365
   366    decode_segment(s, length, buf);
   367
   368    *optionsize = written + segmentlen;
   369
   370    return 0;
   371  }
