   388  /**
   389   * Splits the given string into segments. You should call one of the
   390   * macros coap_split_path() or coap_split_query() instead.
   391   *
   392   * @param s      The URI string to be tokenized.
   393   * @param length The length of @p s.
   394   * @param h      A handler that is called with every token.
   395   * @param data   Opaque data that is passed to @p h when called.
   396   *
   397   * @return The number of characters that have been parsed from @p s.
   398   */
   399  static size_t
   400  coap_split_path_impl(const uint8_t *s, size_t length,
   401                       segment_handler_t h, void *data) {
   402
   403    const uint8_t *p, *q;
   404
   405    p = q = s;
   406    while (length > 0 && !strnchr((const uint8_t *)"?#", 2, *q)) {
   407      if (*q == '/') {                /* start new segment */
   408
   409        if (!dots(p, q - p)) {
   410          h(p, q - p, data);
   411        }
   412
   413        p = q + 1;
   414      }
   415
   416      q++;
   417      length--;
   418    }
   419
   420    /* write last segment */
   421    if (!dots(p, q - p)) {
   422      h(p, q - p, data);
   423    }
   424
   425    return q - s;
   426  }
