   561  coap_string_t *coap_get_query(const coap_pdu_t *request) {
   562    coap_opt_iterator_t opt_iter;
   563    coap_opt_filter_t f;
   564    coap_opt_t *q;
   565    coap_string_t *query = NULL;
   566    size_t length = 0;
   567    static const uint8_t hex[] = "0123456789ABCDEF";
   568
   569    coap_option_filter_clear(&f);
   570    coap_option_filter_set(&f, COAP_OPTION_URI_QUERY);
   571    coap_option_iterator_init(request, &opt_iter, &f);
