  1109  coap_pdu_parse(coap_proto_t proto,
  1110                 const uint8_t *data,
  1111                 size_t length,
  1112                 coap_pdu_t *pdu)
  1113  {
  1114    size_t hdr_size;
  1115
  1116    if (length == 0)
  1117      return 0;
  1118    hdr_size = coap_pdu_parse_header_size(proto, data);
  1119    if (!hdr_size || hdr_size > length)
  1120      return 0;
  1121    if (hdr_size > pdu->max_hdr_size)
  1122      return 0;
  1123    if (!coap_pdu_resize(pdu, length - hdr_size))
  1124      return 0;
  1125  #ifndef WITH_LWIP
  1126    memcpy(pdu->token - hdr_size, data, length);
  1127  #endif
  1128    pdu->hdr_size = (uint8_t)hdr_size;
  1129    pdu->used_size = length - hdr_size;
  1130    return coap_pdu_parse_header(pdu, proto) && coap_pdu_parse_opt(pdu);
  1131  }
