   139  COAP_STATIC_INLINE int
   140  opt_finished(coap_opt_iterator_t *oi) {
   141    assert(oi);
   142
   143    if (oi->bad || oi->length == 0 ||
   144        !oi->next_option || *oi->next_option == COAP_PAYLOAD_START) {
   145      oi->bad = 1;
   146    }
   147
   148    return oi->bad;
   149  }
